const b = $input.first().json.body || {};
const a = String(b.action || '');
const ALL = ['list', 'view', 'diff', 'activate', 'rollback', 'revoke', 'edit', 'delete', 'restore', 'chat_history', 'unanswered', 'mark_handled'];
if (!ALL.includes(a)) throw new Error('Hành động không hợp lệ');
const id = String(b.doc_version_id || '').trim(), doc = String(b.document_id || '').trim();
const BYID = ['view', 'diff', 'activate', 'edit', 'delete', 'restore'];
if (BYID.includes(a) && !/^[0-9a-f-]{36}$/i.test(id)) throw new Error('doc_version_id không hợp lệ');
if ((a === 'rollback' || a === 'revoke') && !/^[A-Za-z0-9_-]{1,100}$/.test(doc)) throw new Error('document_id không hợp lệ');

const WRITE = ['activate', 'rollback', 'revoke', 'edit', 'delete', 'restore'];
let actor = String(b.actor || '').replace(/\s+/g, ' ').trim();
if (WRITE.includes(a)) {
  if (actor.length < 2 || actor.length > 60) throw new Error('Hãy nhập tên người thực hiện (2 đến 60 ký tự).');
} else { actor = ''; }

const actor_role = String(b.actor_role || (b.role || 'super_admin')).toLowerCase();
const actor_branch = String(b.actor_branch || (b.branch || 'all')).toLowerCase();

let title = '', doc_number = '', effective_date = '', expiry_date = '';
let branch_scope = '', doc_type = '', role_access = '', change_summary = '';
if (a === 'edit') {
  title = String(b.title || '').trim();
  doc_number = String(b.doc_number || '').trim();
  effective_date = String(b.effective_date || '').trim();
  expiry_date = String(b.expiry_date || '').trim();
  branch_scope = String(b.branch_scope || '').trim();
  doc_type = String(b.doc_type || '').trim();
  role_access = String(b.role_access || '').trim();
  change_summary = String(b.change_summary || '').trim();
  if (!title || title.length > 300) throw new Error('Tiêu đề không được để trống và tối đa 300 ký tự.');
  if (doc_number.length > 100) throw new Error('Số văn bản tối đa 100 ký tự.');
  if (effective_date && !/^\d{4}-\d{2}-\d{2}$/.test(effective_date)) {
    throw new Error('Ngày hiệu lực không đúng định dạng YYYY-MM-DD.');
  }
}
const target = BYID.includes(a) ? id : (a === 'list' || a === 'chat_history' || a === 'unanswered' || a === 'mark_handled' ? '00000000-0000-0000-0000-000000000000' : doc);
return [{ json: { action: a, target, actor, actor_role, actor_branch, title, doc_number, effective_date, expiry_date, branch_scope, doc_type, role_access, change_summary, ids: String(b.ids || ''), mode: String(b.mode || 'handled') } }];
